#include <bits/stdc++.h>
using namespace std;

int process(int A[], int B[], int order[]) {
    int sum = 0;
    for (int idx : order) {
        int bVal = B[idx];
        for (int j = 0; j < 3; j++) {
            int minVal = std::min(A[j], bVal);
            A[j] -= minVal;
            bVal -= minVal;
        }
        sum += A[0] + A[1] + A[2];
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> parts(3);
    for (int i = 0; i < 3; i++) {
        cin >> parts[i];
    }
    int a1 = parts[0], a2 = parts[1], a3 = parts[2];

    for (int i = 0; i < 3; i++) {
        cin >> parts[i];
    }
    int b1 = parts[0], b2 = parts[1], b3 = parts[2];

    int maxVal = std::min(a1, b2) + std::min(a2, b3) + std::min(a3, b1);

    int A[3] = {a1, a2, a3};
    int B[3] = {b1, b2, b3};
    int results[6];

    int orders[6][3] = {
        {0, 1, 2},
        {2, 1, 0},
        {1, 2, 0},
        {0, 2, 1},
        {2, 0, 1},
        {1, 0, 2}
    };

    for (int i = 0; i < 6; i++) {
        int A_copy[3], B_copy[3];
        std::copy(A, A + 3, A_copy);
        std::copy(B, B + 3, B_copy);
        results[i] = process(A_copy, B_copy, orders[i]);
    }

    int minVal = *std::min_element(results, results + 6);
    cout << minVal << " " << maxVal << "\n";

    return 0;
}

